script:
card({ name: "Task board", icon: 'tasks', nav: { each: true } });
const words = {
  todo: "To do",
  doing: "Doing",
  done: "Done",
  add: "Add a task",
  empty: "Nothing here yet",
  take: "I'll do it",
  drop: "Let it go",
  by: "{p0} is on it",
  free: "Nobody's on it",
  note: "Add a note",
  back: "Back",
  remove: "Remove",
  gone: "That task is gone",
  full: "Forty tasks at most",
  onlySender: "Only the person who sent the card can do that",
};

// Anyone adds, takes and moves tasks; only the sender removes them.
const stages = [words.todo, words.doing, words.done];
const tones = ['muted', 'accent', 'success'];

function init() {
  return { tasks: [], next: 1, open: {} };
}

// The task this person has open.
function task(s, id) {
  const t = s.tasks.find(t => t.id === s.open[id]);
  if (!t) throw words.gone;
  return t;
}

on.add = (s, args) => {
  const title = String(args.value || '').trim().slice(0, 80);
  if (!title) return;
  if (s.tasks.length >= 40) throw words.full;
  s.tasks.push({ id: s.next++, title, stage: 0, who: null, whoName: '', notes: [] });
};

on.open = (s, args, ctx) => {
  s.open[ctx.author] = args.task;
  ctx.push('task');
};

on.move = (s, args, ctx) => {
  const t = task(s, ctx.author);
  t.stage = Math.min(2, Math.max(0, t.stage + args.by));
};

on.take = (s, args, ctx) => {
  const t = task(s, ctx.author);
  const mine = t.who === ctx.author;
  t.who = mine ? null : ctx.author;
  t.whoName = mine ? '' : ctx.authorName;
};

on.note = (s, args, ctx) => {
  const note = String(args.value || '').trim().slice(0, 200);
  if (note) task(s, ctx.author).notes.push(ctx.authorName + ': ' + note);
};

on.remove = (s, args, ctx) => {
  if (ctx.author !== ctx.sender) throw words.onlySender;
  const t = task(s, ctx.author);
  s.tasks = s.tasks.filter(x => x !== t);
  ctx.pop();
};

function view(s) {
  return column([
    ...stages.map((name, i) => {
      const here = s.tasks.filter(t => t.stage === i);
      return column([
        row([text(name, { bold: true }), badge(String(here.length), { tone: tones[i] })], { align: 'between' }),
        here.length
          ? here.map(t => button(t.title + (t.whoName ? ' · ' + t.whoName : ''), 'open', { task: t.id }, { tone: i === 2 ? 'muted' : undefined }))
          : text(words.empty, { size: 'small', tone: 'muted' }),
      ]);
    }),
    input('task', words.add, 'add'),
  ]);
}

screens.task = (s, me) => {
  const t = s.tasks.find(t => t.id === s.open[me.id]);
  if (!t) return column([text(words.gone, { tone: 'muted' }), button(words.back, 'pop')]);
  const mine = t.who === me.id;
  return column([
    text(t.title, { size: 'large', bold: true }),
    row([badge(stages[t.stage], { tone: tones[t.stage] }), text(t.who ? words.by.replace('{p0}', t.whoName) : words.free, { size: 'small', tone: 'muted' })]),
    row([
      t.stage > 0 && button('◀ ' + stages[t.stage - 1], 'move', { by: -1 }),
      t.stage < 2 && button(stages[t.stage + 1] + ' ▶', 'move', { by: 1 }, { tone: 'accent' }),
      button(mine ? words.drop : words.take, 'take', null, { tone: mine ? 'muted' : 'success' }),
    ]),
    ...t.notes.map(n => text(n, { size: 'small' })),
    input('note', words.note, 'note'),
    row([button(words.back, 'pop'), me.isSender && button(words.remove, 'remove', null, { tone: 'danger' })], { align: 'between' }),
  ]);
};
